// NIOGEN | n8n/cadencia/c02_interruptor.js — nó "2 · Interruptor" do mari_cadencia (04/11/2026)
// Kill switch e modo da cadência (staticData). Padrão: DESLIGADA e em modo 'teste'.
//   _cadenciaAtiva  false | true      → false = a rodada para aqui (nada é lido nem enviado)
//   _modoCadencia   'teste' | 'chatwoot'
//       teste    → só conversas canal 'teste' (rota /webhook/mari-teste); envio SIMULADO (grava turno + toque)
//       chatwoot → só conversas canal 'whatsapp'; envio real pela API do Chatwoot (nós 6g/7 hoje desligados)
// Comandos pela rota admin (header X-Mari-Secret): ligar | desligar | modo teste | modo chatwoot | status
// Sem texto de negócio e sem segredo.

const sd = $getWorkflowStaticData('global');
if (sd._cadenciaAtiva === undefined) sd._cadenciaAtiva = false;
if (!sd._modoCadencia) sd._modoCadencia = 'teste';

const ex = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const estado = () => ({ ativa: sd._cadenciaAtiva, modo: sd._modoCadencia, ultima_rodada: sd._ultimaRodada || null });

if (ex('1w · Admin cadência')) {
  const body = $('1w · Admin cadência').first().json.body || {};
  const cmd = String(body.admin || '').toLowerCase().trim();
  if (cmd === 'ligar') sd._cadenciaAtiva = true;
  else if (cmd === 'desligar') sd._cadenciaAtiva = false;
  else if (cmd === 'modo teste' || cmd === 'modo chatwoot') sd._modoCadencia = cmd.split(' ')[1];
  else if (cmd !== 'status') return [{ json: { admin: true, resposta: { erro: 'use: ligar | desligar | modo teste | modo chatwoot | status' } } }];
  return [{ json: { admin: true, resposta: { admin: true, ...estado() } } }];
}

if (!sd._cadenciaAtiva) return [];   // kill switch: nada roda

sd._ultimaRodada = new Date().toISOString();
return [{ json: {
  admin: false,
  modo: sd._modoCadencia,
  canal: sd._modoCadencia === 'chatwoot' ? 'whatsapp' : 'teste',
  agora: sd._ultimaRodada,
  limite: 30,
} }];

// NIOGEN | n8n/cadencia/c03_itens.js — nó "3b · Itens" do mari_cadencia (04/11/2026)
// A RPC mari_cadencia_candidatos devolve um array de objetos (cada um já com a decisão do banco:
// passo, ação, texto, template, params). Aqui só vira um item por conversa — sem decisão nenhuma.
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const lista = Array.isArray(j) ? j : (j && j.conversa_id ? [j] : []);
  for (const c of lista) {
    const v = (c && c.mari_cadencia_candidatos) || c;   // PostgREST pode embrulhar setof jsonb no nome da função
    if (v && v.conversa_id && v.pode_enviar === true) out.push({ json: v });
  }
}
return out.slice(0, 30);   // teto por rodada (o banco já limita; aqui é cinto + suspensório)

// NIOGEN | n8n/cadencia/c05_montar.js — nó "5 · Montar envio" do mari_cadencia (04/11/2026)
// Recebe UM candidato (loop de 1) e monta o corpo da mensagem para a API do Chatwoot:
//   texto livre (dentro da janela de 24 h) → { content, message_type, private:false }
//   template (fora da janela)              → { content: corpo renderizado, template_params: { name, category,
//                                              language, processed_params: { body: { "1": …, "2": … } } } }
// (formato do noF4b da Renata, capturado do payload da própria UI do Chatwoot).
// semEnvio = true quando NÃO há envio real: modo teste, canal 'teste', telefone de teste 5500000000xxx ou
// passo ENCERRAR (só muda o status). Nunca o nome da revendedora no texto (o banco já filtra; aqui de novo).

const CONFIG = {
  CHATWOOT_NIO_ACCOUNT: '',   // preencher na virada para o modo chatwoot (conta própria da Nio, nunca a da Vero)
};

const c = $input.first().json;
const modo = $('2 · Interruptor').first().json.modo;
const tel = String(c.telefone || '');
const texto = String(c.texto || '');

const PROIBIDO = new RegExp(['dh' + 'arma', 'gr[aá]tis', 'gratuit', 'combo', 'pacote', 'nio 5g', '2028', 'sem fidelidade'].join('|'), 'i');
let erro = null;
if (c.acao !== 'encerrar' && (!texto || PROIBIDO.test(texto) || texto.includes('*'))) erro = 'texto vazio ou reprovado no filtro de saída';

const semEnvio = c.acao === 'encerrar' || modo !== 'chatwoot' || c.canal === 'teste' || tel.startsWith('5500000000');

let corpo = null;
if (c.acao === 'texto') {
  corpo = { content: texto, message_type: 'outgoing', private: false };
} else if (c.acao === 'template') {
  const body = {};
  (c.params || []).forEach((v, i) => { body[String(i + 1)] = String(v); });
  corpo = {
    content: texto, message_type: 'outgoing', content_type: 'text',
    template_params: { name: c.template, category: c.categoria || 'MARKETING', language: 'pt_BR', processed_params: { body } },
  };
}

if (!semEnvio && !c.chatwoot_conversation_id) erro = erro || 'conversa sem chatwoot_conversation_id';
if (!semEnvio && !CONFIG.CHATWOOT_NIO_ACCOUNT) erro = erro || 'CHATWOOT_NIO_ACCOUNT vazio';

return [{ json: {
  conversaId: c.conversa_id,
  passo: c.proximo_passo,
  acao: c.acao,
  texto,
  excecao: c.excecao || null,
  semEnvio: semEnvio && !erro,
  erro,
  chatwootConversationId: c.chatwoot_conversation_id || null,
  corpo,
  config: CONFIG,
} }];

// NIOGEN | n8n/cadencia/c06_guard.js — nó "6h · Guard Chatwoot" do mari_cadencia (04/11/2026)
// Antes de QUALQUER envio real, relê a conversa no Chatwoot (padrão noF1 da Renata):
// humano atribuído, time atribuído ou conversa resolvida → para a escada (mari_cadencia_parar) e não envia.
// Sem resposta do Chatwoot (nó 6g desligado ou erro) → NÃO envia: vira falha (não queima o passo).
const m = $('5 · Montar envio').first().json;
const cw = $input.first().json || {};
const temDados = cw && (cw.id !== undefined || cw.status !== undefined) && !cw.conversaId;

if (!temDados) {
  return [{ json: { ...m, parar: false, enviar: false, ok: false, erro: 'guard do Chatwoot sem resposta (nó desligado ou erro) — não enviado' } }];
}
const humano = !!(cw.meta && cw.meta.assignee) || !!cw.assignee_id;
const time = !!cw.team_id || !!(cw.meta && cw.meta.team);
const resolvida = cw.status === 'resolved';
const parar = humano || time || resolvida;
return [{ json: { ...m, parar, enviar: !parar, humano, time, resolvida } }];

// NIOGEN | n8n/cadencia/c07_resultado.js — nó "7r · Resultado" do mari_cadencia (04/11/2026)
// Lê a resposta do POST no Chatwoot: ok só com id da mensagem e status ≠ 'failed' (a Meta recusou).
// Nó 7 desligado → chega o próprio item montado (sem id) → falha registrada, passo não queima.
const g = $('6h · Guard Chatwoot').first().json;
const r = $input.first().json || {};
const ok = !!r.id && r.status !== 'failed' && !r.conversaId;
return [{ json: { ...g, ok, erro: ok ? null : (r.error || r.message || `chatwoot sem id (status=${r.status || 'nenhum'})`) } }];
